public class TokenMapper extends Mapper<LongWritable, Text, Text, IntWritable> {
    private static final IntWritable ONE = new IntWritable(1);
    private final Text word = new Text();

    @Override
    protected void map(LongWritable offset, Text line, Context ctx) throws IOException, InterruptedException {
        for (String w : line.toString().toLowerCase().split("[^a-z]+")) {
            if (w.isEmpty()) continue;
            word.set(w);
            ctx.write(word, ONE);                      // (word, 1)
        }
    }
}

public class SumReducer extends Reducer<Text, IntWritable, Text, IntWritable> {
    @Override
    protected void reduce(Text word, Iterable<IntWritable> counts, Context ctx) throws IOException, InterruptedException {
        int sum = 0;
        for (IntWritable c : counts) sum += c.get();
        ctx.write(word, new IntWritable(sum));
    }
}

// in the driver: job.setCombinerClass(SumReducer.class);  the reducer doubles as the combiner

