fun badCombine(amounts: List<Long>): Double = amounts.average()

// map task 1 saw merchant m-17 twice: 1,000 and 3,000 cents -> 2,000.0
// map task 2 saw it once: 10,000 cents                         -> 10,000.0
// reducer: (2,000 + 10,000) / 2 = 6,000, but the true average is 14,000 / 3 = 4,666.67

// 2. a partial aggregate that can be combined in any order
data class SumCount(val sum: Long, val count: Long) {
    operator fun plus(other: SumCount) = SumCount(sum + other.sum, count + other.count)
}

fun map(merchantId: String, amountCents: Long) = merchantId to SumCount(amountCents, 1)
fun combine(parts: List<SumCount>): SumCount = parts.reduce(SumCount::plus)
fun reduce(parts: List<SumCount>): Double = parts.reduce(SumCount::plus).let { it.sum.toDouble() / it.count }

