fun partition(key: String, reducers: Int): Int =
    (key.hashCode() and Int.MAX_VALUE) % reducers      // never negative, same key -> same reducer

fun shuffle(mapOutputs: List<List<KV>>, reducers: Int): Pair<List<List<KV>>, Long> {
    val buckets = List(reducers) { mutableListOf<KV>() }
    var bytes = 0L
    for (task in mapOutputs) for (kv in task) {
        buckets[partition(kv.key, reducers)] += kv
        bytes += kv.key.toByteArray(Charsets.UTF_8).size + 4
    }
    return buckets.map { b -> b.sortedBy { it.key } } to bytes
}

